async function submit(action,retry=null){if(testing){if(busy||b)return;try{const before=s;testSession=testAction(testSession,action);snap=testSession.snapshot;s=snap.state;resourceFeedback.action(before,action,s,crypto.randomUUID());if(['prepare','backDay','nextDay','retryDay'].includes(action.type))overlayTab=null;if(action.type==='recruit')memberView=action.person;panelKey='';render();}catch(e){error(e.message);}return;}const restarting=action.type==='restart';if(busy||b&&!restarting||pending?.action.type==='restart'&&!restarting||restarting&&(savingNight||startingNight))return;if(restarting)clearTimeout(saveTimer);busy=true;render();const request=retry||{runId:snap.runId,revision:snap.revision,requestId:crypto.randomUUID(),action};pending=request;
 try{const send=()=>campaignStorage.action(request);const data=await (restarting&&releaseNightLock?send():withEditLock(send));if(!restarting&&data.runId===snap.runId&&data.revision>snap.revision)resourceFeedback.action(s,action,data.state,request.requestId);if(action.type==='rebuildBuilding'){const old=s.buildings.find(q=>q.id===action.id);facility=action.building;buildingView=data.state.buildings.find(q=>q.plot===old?.plot)?.id||'';}if(restarting){discardNight();selectedPerson=memberView='hero';selectedZone='gate';mapMoveArmed=false;mapMoveMessage='';tab='yard';lastPhase=null;$('#error').hidden=true;}$('#error').hidden=true;snap=data;s=data.state;if(['chooseRole','prepare','backDay','nextDay','retryDay','restart'].includes(action.type))overlayTab=null;if(action.type==='recruit')memberView=action.person;pending=null;panelKey='';}
 catch(e){if(e.snapshot){snap=e.snapshot;s=snap.state;}if((e.status&&e.status<500)||e.name==='RuleError')pending=null;error(`${e.message}${pending?'。请点「重试保存」，不会重复消耗。':''}`);if(pending)$('#error').insertAdjacentHTML('beforeend',' <button class="button small" data-action="retry-action">重试保存</button>');}finally{busy=false;render();}}
// A dedicated worker runs the whole night. No WebSocket, heartbeat or network
// request is involved between starting and finishing a night.
let workerReadyResolve,releaseNightLock=null,localResult=null,savingNight=false,saveTimer=null,saveAttempts=0,saveConflict=false,uiTimer=null;
const discardedNightIds=new Set();
function discardNight(){if(b)discardedNightIds.add(b.id);clearTimeout(saveTimer);clearTimeout(uiTimer);uiTimer=null;localResult=null;saveAttempts=0;saveConflict=false;b=null;connected=false;controller=false;nightWorker.postMessage({type:'dispose'});releaseNightLock?.();releaseNightLock=null;resourceFeedback.beginNight();}
const workerReady=new Promise(resolve=>{workerReadyResolve=resolve;});
const nightWorker=new Worker(new URL('./night-worker.js',import.meta.url),{type:'module'});
let localMessages=0,uiRenders=0,simulatedSteps=0;
Object.defineProperty($('#world'),'getNightSnapshot',{value:()=>b&&structuredClone(b)});
Object.defineProperty($('#world'),'getNightDiagnostics',{value:()=>({runtime:'worker',messages:localMessages,renders:uiRenders,steps:simulatedSteps,saving:savingNight,pendingSave:!!localResult})});
function scheduleRender(){if(uiTimer)return;uiTimer=setTimeout(()=>{uiTimer=null;render();},200);}
nightWorker.addEventListener('message',({data})=>{
 if(data.type==='ready'){workerReadyResolve();return;}
 if(data.type==='error'){error(data.message);return;}
 if(data.type!=='state'||discardedNightIds.has(data.battle?.id))return;
 localMessages++;simulatedSteps=data.steps;
 const wasPaused=b?.paused;b=data.battle;connected=true;controller=true;
 resourceFeedback.night(b,data.result,s.resources);
 // Show settled health and conditions while the completed night awaits saving.
 if(data.result)for(const person of b.people){const settled=data.result.people.find(p=>p.id===person.id);if(settled)Object.assign(person,settled);}
 scene.set(s,b,selectedZone,selectedPerson,mapMoveArmed);
 if(data.result&&testing){try{testSession=finishTestNight(testSession,data.result);snap=testSession.snapshot;s=snap.state;discardNight();overlayTab=isEnding(s)?'ending':'report';panelKey='';render();}catch(e){error(e.message);}return;}
 if(data.result&&!localResult){localResult={runId:snap.runId,revision:snap.revision,nightId:b.id,orderModel:'temporary-v1',result:data.result};if(isEnding(data.result))overlayTab='ending';saveLocalNight();}
 if(b.paused!==wasPaused||b.finished||resourceFeedback.pending)render();else scheduleRender();
});
