async function withEditLock(fn){
 if(!navigator.locks)return fn();
 return navigator.locks.request('campaign-'+snap.runId,{ifAvailable:true},lock=>{if(!lock)throw Error('另一个页面正在进行本地夜战，请先在那个页面结束或关闭。');return fn();});
}
async function acquireNightLock(){
 if(!navigator.locks)return true;
 return new Promise((resolve,reject)=>navigator.locks.request('campaign-'+snap.runId,{ifAvailable:true},async lock=>{
  if(!lock){resolve(false);return;}
  await new Promise(release=>{releaseNightLock=release;resolve(true);});
 }).catch(reject));
}
let startingNight=false;
async function connect(){
 if(b||startingNight||busy||pending)return;startingNight=true;
 try{
  if(!testing){
   if(!await acquireNightLock())throw Error('另一个页面正在进行本地夜战，请在那个页面继续，或关闭后重新开始。');
   const latest=await campaignStorage.read();
   if(!latest||latest.runId!==snap.runId||latest.revision!==snap.revision){if(latest){snap=latest;s=latest.state;render();}throw Error('其他页面已经修改进度，请检查最新准备后再开始。');}
  }
  await workerReady;saveAttempts=0;saveConflict=false;
  resourceFeedback.beginNight();
  nightWorker.postMessage({type:'init',base:snap,options:{autoPause:autoPauseEnabled}});
 }catch(e){releaseNightLock?.();releaseNightLock=null;error(e.message);}
 finally{startingNight=false;}
}
function raw(message){if(message.action)nightWorker.postMessage({type:'command',...message});}
function command(action){if(!b||b.finished||pending?.action.type==='restart')return;raw({commandId:crypto.randomUUID(),action});}
async function saveLocalNight({manual=false}={}){
 if(testing)return;
 if(!localResult||savingNight||pending?.action.type==='restart'||saveConflict&&!manual)return;
 // Retry the retained result through the same atomic revision check.
 if(manual)saveConflict=false;
 clearTimeout(saveTimer);savingNight=true;render();
 try{
  const data=await campaignStorage.finishNight(localResult);
  snap=data;s=data.state;b=null;connected=false;controller=false;localResult=null;
  nightWorker.postMessage({type:'dispose'});releaseNightLock?.();releaseNightLock=null;panelKey='';
  $('#error').hidden=true;
 }catch(e){
  saveConflict=[400,404,409,422].includes(e.status)||e.name==='RuleError';
  saveAttempts++;if(b){b.reason='已在本机结束；浏览器存档待重试，请保持页面。';b.saveError=e.message;}
  if(saveAttempts===1||saveConflict)error(`${e.message}。本地结果已保留在当前页面，尚未写入存档。`);
  if(!saveConflict)saveTimer=setTimeout(saveLocalNight,Math.min(30000,2000*2**Math.min(saveAttempts-1,4)));
 }finally{savingNight=false;render();}
}
