function reportPanel(){const r=s.report;const bossOutcome=r?.boss?`<p class="copy" data-testid="boss-report">首领 ${escape(r.boss.name)} · ${r.boss.defeated?'已击退':'未击退'}${r.boss.id==='broodmother'?` · 封巢${r.boss.sealed}次，幼兽${r.boss.summons}只`:r.boss.id==='twinvein'?` · 共生复苏${r.boss.revives}次`:''}</p>`:'';const outcome=(r?.dog?`<p class="copy" data-testid="dog-report">小麦守夜：汪汪${r.dog.barks}次，让生物稍稍退开${r.dog.retreats}次 · 口粮${r.dog.foodUsed}食物。</p>`:'')+bossOutcome+(r?.challenge?`<div class="notice ${r.challenge.status==='cleared'?'':'danger'}" data-testid="challenge-result"><b>${escape(r.challenge.title)} · ${r.challenge.status==='cleared'?'挑战完成':'本次未完成'}</b><br>${escape(r.challenge.feedback)}${r.challenge.status==='cleared'?`<br>奖励：建材+${CHALLENGE_REWARD.materials}，全员恐惧−${CHALLENGE_REWARD.fear}。`:''}</div>`:'');const tabs=(isEnding(s)?button('返回结局画面','drawer',attrs({panel:'ending'}),'small'):'')+subTabs([['summary','战报概况'],['events','本夜记录']],reportSub,'report');if(reportSub==='events')return tabs+logList((r?.events||[]).slice().reverse());if(s.phase==='rescued')return tabs+outcome+lead('倒计时归零 · 救援黎明','我们等到了',escape(s.ending.text))+`<p class="copy">离开的成员：${s.ending.people.join('、')}。${s.ending.closePickup?'救援抵近院子接应。':'你们按广播前往公共集合点。'} 帮助邻里 ${s.ending.helped} 次。</p><p class="copy">带走的纪念：${s.memories.join('、')||'一张写满二十八天的手记'}；夜间挑战完成${s.achievements?.length||0}/28。</p>${r?.elapsed!==undefined?`<div class="row" data-testid="night-elapsed"><span>最后一夜守夜用时</span><b>${r.elapsed}秒</b></div>`:''}`;return tabs+outcome+harvestNotice()+lead('第 '+s.day+(r.period==='day'?' 天 · ':' 夜 · ')+(testing?'测试结果，仅本页有效':'结果已保存'),s.phase==='failed'?'这一天可以重新安排':'天亮了，院子还在',s.phase==='failed'?'可以免费回到当天清晨，改变准备和安排。':allPeople().length>1?'有人把热水留在窗边。今天，我们还在一起。':'你往炉边挪了挪杯子，窗外开始泛白。')+`${r.elapsed!==undefined?`<div class="row" data-testid="night-elapsed"><span>守夜用时</span><b>${r.elapsed}秒</b></div>`:''}<div class="row"><span>幸存人数 / 房屋</span><b>${allPeople().length} 人 / ${formatDurability(s.house)}</b></div><div class="row"><span>食物 / 净水</span><b>消耗 ${r.foodUsed} / ${r.waterUsed}</b></div><div class="row"><span>建材 / 燃料</span><b>消耗 ${r.materialsUsed} / ${r.fuelUsed}</b></div><div class="row"><span>突破防线</span><b>${r.breaches} 处</b></div>${s.buildings.some(b=>buildingHealth(b)<BUILDING_MAX_HP)?`<div class="notice danger" data-testid="facility-damage">院内设施：${s.buildings.filter(b=>buildingHealth(b)<BUILDING_MAX_HP).map(b=>`${BUILDINGS[b.type].name} ${formatDurability(buildingHealth(b))}/${BUILDING_MAX_HP}${buildingHealth(b)===0?"（损毁，停止生效）":"（受损）"}`).join("、")}。受损设施可花${BUILDING_REPAIR.ap}行动${BUILDING_REPAIR.materials}建材维修；损毁设施需按新造价原址重建，或清理废墟腾位。</div>`:""}${r.defenseLosses?.length?`<div class="notice danger" data-testid="defense-losses">附属设施损毁：${r.defenseLosses.map(loss=>`${ZONES.find(z=>z.id===loss.zone).name} · ${loss.defenses.map(escape).join('、')}`).join('；')}。修好护栏后可重新安装。</div>`:''}${nutritionWarning(r,true)}${r.deaths.length?`<div class="notice danger">死亡成员：${r.deaths.join('、')}。${s.phase==='failed'?'可重试当天，调整准备与防守安排。':'可以重试当天，或接受结果继续。'}</div>`:''}`;}
