 if(action==='night-cmd'){mapMoveMessage='';command({type:a.command,person:selectedPerson,target:['fire','stoke','addWood','extinguish'].includes(a.command)?'central':selectedZone});return;}if(action==='night-fire'){command({type:a.command||campfireMaintenance(b.fires.find(f=>f.id==='central'),b.resources.materials),person:selectedPerson,target:'central'});return;}
