function storyCard(){
 const story=dayStory(s);return `<div class="story-card"><div class="eyebrow">第 ${s.day} 天 · 院子里的故事</div><h3>${story.title}</h3><p class="copy">${escape(story.text)}</p>${story.choices.map(c=>{const available=actionAvailability(s,{type:'event',choice:c.id});return `<section class="card" data-testid="story-choice"><h3>${escape(c.label.split(' · ')[0])}</h3><p class="mini">消耗：${costText(c.ap,c.cost)}。</p><p class="copy" data-testid="story-effect">${escape(storyEffect(s,c))}</p>${button('执行这项安排','event',attrs({choice:c.id})+(available.allowed?'':' disabled'),'primary')}${available.allowed?'':`<p class="mini">${escape(available.reason)}</p>`}</section>`;}).join('')}</div>`;
}
function nightMembersPanel(){const people=b.people.filter(p=>!p.dead);if(!people.length)return noLivingPanel();if(!people.some(p=>p.id===memberView))memberView=people[0].id;const p=people.find(p=>p.id===memberView);return `<div class="member-tabs">${people.map(q=>button(portrait(q.id,q.name)+`<span>${q.name}</span>`,'member-view',attrs({person:q.id}),memberView===q.id?'selected':'')).join('')}</div>${subTabs([['status','状态'],['skills','技能']],memberSub==='skills'?'skills':'status','member')}${memberSub==='skills'?skillsPanel(p):`<h3>${p.name} · ${personRole(p)}</h3>${orderCard(p)}<p class="mini">长期岗位在白天／黄昏「成员 → 分工」修改；临时指令完成后自动恢复。</p>${nutritionBadges(p)}<div class="stat-grid person-stats">${[['健康',p.health],['恐惧',p.fear],['疲劳',p.fatigue],['体力',p.stamina]].map(([name,n])=>`<div class="stat"><span>${name}</span><b>${Math.round(n)}/${name==='体力'?maxStamina(p):100}</b></div>`).join('')}</div><p class="mini" data-testid="stamina-note">体力上限 ${maxStamina(p)} · ${staminaProfile(p).staminaNote}</p>${fatiguePanel(p)}${fearPanel(p,b)}${p.wound==='severe'?`<p class="copy">重伤：第${p.deadline}日结束前需要稳定救治；屋外仍会受攻击，健康归零即死亡。</p>`:''}<p class="mini">${Object.entries(p.skills).map(([k,v])=>`${SKILL_NAMES[k]} ${v.toFixed(1)}`).join(' · ')}</p><div class="actions">${button('技能说明 · 查看各级收益','subtab',attrs({group:'member',value:'skills'}),'small')}</div><div class="actions">${button('设为执行者，回到战场','actor-from-sheet',attrs({person:p.id}),'primary')}</div>`}`;}
